import readline from 'node:readline';
const send=v=>process.stdout.write(JSON.stringify({jsonrpc:'2.0',...v})+'\n');let session='fake-session';
readline.createInterface({input:process.stdin}).on('line',line=>{const m=JSON.parse(line);if(m.method==='initialize')send({id:m.id,result:{protocolVersion:1}});else if(m.method==='session/new')send({id:m.id,result:{sessionId:session}});else if(m.method==='session/prompt'){const text=m.params.prompt[0].text;if(text.includes('permission-test'))send({id:999,method:'session/request_permission',params:{sessionId:session,toolCall:{title:'Run a command?'},options:[{optionId:'yes',kind:'allow_once',name:'Allow once'},{optionId:'no',kind:'reject_once',name:'Deny'}]}});else if(text.includes('wait-test'))return;else{send({method:'session/update',params:{sessionId:session,update:{sessionUpdate:'agent_message_chunk',content:{type:'text',text:'{"changes":[{"op":"title","text":"Pelican 🐦"}]}'}}}});send({id:m.id,result:{stopReason:'end_turn'}});}}else if(m.id===999){send({method:'session/update',params:{sessionId:session,update:{sessionUpdate:'agent_message_chunk',content:{type:'text',text:m.result.outcome.optionId}}}});}else if(m.method==='session/cancel')send({method:'session/update',params:{sessionId:session,update:{sessionUpdate:'agent_message_chunk',content:{type:'text',text:'cancelled'}}}});});
